files.fixture-installer:
#!/bin/bash
[[ $UID == 2000 && $EUID == 2000 && $PWD == /tmp/parity-case && $HOME == /tmp/parity-home && -O /tmp/parity-case && -O /tmp/parity-home && -r /etc/bashos-parity-vm && -r /sys/class/dmi/id/sys_vendor ]] || { echo 'not a disposable parity guest' >&2; exit 98; }
marker=$(< /etc/bashos-parity-vm); vendor=$(< /sys/class/dmi/id/sys_vendor)
[[ $marker =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ && $vendor == QEMU ]] || { echo 'guest identity mismatch' >&2; exit 98; }
printf 'CALL\0%s\0%s\0' "$BASH" "$0" >> "$HOME/calls.bin"
printf '%s\0' "$@" >> "$HOME/calls.bin"
printf 'END\0' >> "$HOME/calls.bin"
printf 'ENV\0%s\0%s\0%s\0' "${PAYLOAD_ROOT-unset}" "${PAYLOAD_REPO-unset}" "${FIXTURE_TOKEN-unset}" >> "$HOME/env.bin"
case ${MOCK_MODE-0} in
  exit3) exit 3 ;;
  signal) kill -TERM "$$"; exit 99 ;;
  rollbackfail) case ${!#} in T-bad) exit 3 ;; T-late) exit 6 ;; esac ;;
  snapshot) if [[ ${!#} == T-one ]]; then /usr/bin/rm -f /tmp/parity-case/root/var/lib/bl-pkg/installed/beta; fi ;;
esac
exit 0

cases.setup_script:
[[ $UID == 2000 && $EUID == 2000 && $PWD == /tmp/parity-case && $HOME == /tmp/parity-home && -O /tmp/parity-case && -O /tmp/parity-home && -r /etc/bashos-parity-vm && -r /sys/class/dmi/id/sys_vendor ]] || { echo 'not a disposable parity guest' >&2; exit 98; }
marker=$(< /etc/bashos-parity-vm); vendor=$(< /sys/class/dmi/id/sys_vendor)
[[ $marker =~ ^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$ && $vendor == QEMU ]] || { echo 'guest identity mismatch' >&2; exit 98; }

mkdir -p "$HOME/work"; : > "$HOME/calls.bin"; : > "$HOME/env.bin"

excl=( -path /tmp/parity-case/root -o -path "$HOME/calls.bin" -o -path "$HOME/env.bin" -o -path "$HOME/work" )
snap() {
  {
    /usr/bin/find / -xdev \( -path /proc -o -path /sys \) -prune -o -printf 'sys %p %y %U:%G %m %s %T@ %l\n'
    for d in /tmp /var/tmp /dev/shm /home/parity; do
      /usr/bin/find "$d" \( "${excl[@]}" \) -prune -o -printf 'scratch %p %y %U:%G %m %s %T@ %l\n'
      /usr/bin/find "$d" \( "${excl[@]}" \) -prune -o -type f -exec /usr/bin/sha256sum {} +
    done
  } 2>/dev/null | LC_ALL=C /usr/bin/sort > "$1" || :
  return 0
}

/usr/bin/mkdir /var/tmp/ctl
snap "$HOME/work/c1"
echo control > /var/tmp/ctl/created
snap "$HOME/work/c2"
/usr/bin/cmp -s "$HOME/work/c1" "$HOME/work/c2" && { echo 'CONTROL-FAILED snapshot does not see a created file' >&2; exit 98; }
/usr/bin/rm -f /var/tmp/ctl/created
snap "$HOME/work/c3"
/usr/bin/cmp -s "$HOME/work/c1" "$HOME/work/c3" && { echo 'CONTROL-FAILED snapshot does not see a removal' >&2; exit 98; }
snap "$HOME/work/c4"
/usr/bin/cmp -s "$HOME/work/c3" "$HOME/work/c4" || { echo 'CONTROL-FAILED snapshot is not stable without changes' >&2; /usr/bin/diff "$HOME/work/c3" "$HOME/work/c4" | head -5 >&2; exit 98; }
/usr/bin/wc -l < "$HOME/work/c1" > "$HOME/work/lines"
[ "$(< "$HOME/work/lines")" -gt 1000 ] || { echo 'CONTROL-FAILED snapshot suspiciously small' >&2; exit 98; }
/usr/bin/cp fixture-installer "$HOME/installer"; /usr/bin/chmod 700 "$HOME/installer"

