  "$BASH" "$HOME/installer" "$PAYLOAD_ROOT" "$BASH" "$HOME/installer" "$PAYLOAD_ROOT" "$BASH" "$HOME/installer" "$PAYLOAD_ROOT" > "$HOME/work/expected.bin"
/usr/bin/cmp -s "$HOME/calls.bin" "$HOME/work/expected.bin" && echo calls=three || echo calls=BAD
/usr/bin/cmp -s "$HOME/work/before" "$HOME/work/after" && echo outside=identical || { echo outside=CHANGED; /usr/bin/diff "$HOME/work/before" "$HOME/work/after" | head -10; }
